void change_orientation(double sx, double sy, double dx, double dy) {
	double cos_alpha, alpha, theta, delta;
	double AC, AB;
	bool turnLeft;

	AC = pt_dist(sx, dx, sy, sy);
	AB = pt_dist(sx, dx, sy, dy);

	if (AB == 0)
	{
		return;
	}

	cos_alpha = AC / AB;
	// angle between destination and hor. line
	alpha = acos(cos_alpha);
	// angle between robot axis and hor. line
	theta = ort * 180 / PI;
	// how much the robot should rotate [deg]
	delta = 0.0;
	turnLeft = false;

	if (dx >= sx && dy >= sy)
	{ // Destination in 1st quadrant
		alpha = alpha * (180 / PI);
		if (alpha > theta)
		{
			delta = alpha - theta;
			turnLeft = true;
		}
		else
		{
			delta = theta - alpha;
			turnLeft = false;
		}
	}
	else if (dx >= sx && dy <= sy)
	{ // Destination in 2nd quadrant
		alpha = -alpha * (180 / PI);
		if (theta < alpha)
		{
			delta = alpha - theta;
			turnLeft = true;
		}
		else
		{
			delta = theta - alpha;
			turnLeft = false;
		}
	}
	else if (dx <= sx && dy <= sy)
	{ // Destination in 3rd quadrant
		alpha = -(180 - alpha * (180 / PI));
		if (theta < alpha)
		{
			delta = alpha - theta;
			turnLeft = true;
		}
		else
		{
			delta = theta - alpha;
			turnLeft = false;
		}
	}
	else if (dx <= sx && dy >= sy)
	{ // Destination in 4th quadrant
		alpha = 180 - alpha * (180 / PI);
		if (theta < alpha)
		{
			delta = alpha - theta;
			turnLeft = true;
		}
		else
		{
			delta = theta - alpha;
			turnLeft = false;
		}
	}

	needsTurning = delta > 0.0;

	if (needsTurning && turnLeft)
	{
		ort = ort * 180 / PI + delta;
	}
	else if (needsTurning && !turnLeft)
	{
		ort = ort * 180 / PI - delta;
	}
}

